// === Tab: mySketch ===
let vs = `
   precision highp float;
   precision highp int;

   attribute vec3 aPosition;
   attribute vec2 aTexCoord;

   varying vec2 vTexCoord;

   uniform mat4 uProjectionMatrix;
   uniform mat4 uModelViewMatrix;

   void main() {
      vec4 positionVec4 = vec4(aPosition, 1.0);
      vTexCoord = aTexCoord;
      gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
   }
`;

let Nl = 200.0;

let fs = `
   precision highp float;
   precision highp int;

   varying vec2 vTexCoord;

   ${
      new Array(6)
      .fill()
      .map((_, i) => `uniform vec3 u_color${i};` )
      .join('')
   }
   ${
      new Array(Nl)
      .fill()
      .map((_, i) => `uniform vec4 u_rnd${i};` )
      .join('')
   }

   float pi = 3.14159265358979;

   float gaussian(vec2 pos, vec2 offset, vec2 bin){
      vec2 a = 1.0 / sqrt(2.0 * pi) / bin;
      vec2 b = (pos - offset) / bin;
      vec2 e = a * exp(b * b / -2.0);
      return e.x * e.y;
   }

   float cal_color(vec2 pos, vec4 rnd_n){
      float size;
      float bin;
      vec2 offs;

      size = 0.0005 + rnd_n[0];
      bin = 0.000001 + rnd_n[1];
      offs.x = rnd_n[2] ;
      offs.y = rnd_n[3] ;

      return size * gaussian(pos, offs, vec2(bin));
   }

   void main() {
      vec2 pos = vTexCoord * 2.0 - 1.0;

      vec3 tc = mix(u_color0, u_color1, vTexCoord.x) ;
      vec3 bc = mix(u_color2, u_color3, vTexCoord.x) ;
      vec3 cc = mix(tc, bc, vTexCoord.y) ;
      vec3 cb = mix(u_color4, u_color5, vTexCoord.y) ;

      vec3 color = cc;
      float add_color;

      ${
         new Array(Nl)
         .fill()
         .map((_, ii) => `
            add_color = cal_color(pos, u_rnd${ii});
            color += 0.01 * (cb - cc) * add_color;
         ` )
         .join('')
      }

      float tra = 2.5 * gaussian(pos, vec2(0.0), vec2(0.225));
      tra = min(tra, 1.0);

      gl_FragColor = vec4(color, tra);
    }
`;

const w = 834;
const Ns = 2;
const l = w / Ns;
let theShader = new Array(Ns);

function setup() {
   createCanvas(1112, w, WEBGL);
   setAttributes("alpha", false);
   setAttributes("antialias", true);
   setAttributes("depth", false);
   setAttributes("powerPreference", "high-performance");
   setAttributes("stencil", false);


   textureMode(NORMAL);
   colorMode(HSB);
   rectMode(CENTER);
   noStroke();

   background(0);

   for (let i = 0; i < Ns; i += 1) {
      theShader[i] = new Array(Ns);
      for (let j = 0; j < Ns; j += 1) {
         theShader[i][j] = createShader(vs, fs);
         shader(theShader[i][j]);
         set_uniform(theShader[i][j]);
      }
   }
}

function draw(){
   fill(0, 0, 0, 0);


   for (let i = 0; i < Ns; i += 1) {
      for (let j = 0; j < Ns; j += 1) {
         shader(theShader[i][j]);
         push();
         translate(-w/2, -w/2);
         translate(l * (i + 0.5), l * (j + 0.5));
         rotate(frameCount/97 + 0.5*noise(frameCount/32.3));
         rotateX( 0.4*sin(frameCount/27.7) + 0.3*noise(frameCount/32.34) - frameCount/91);
         rotateY( 0.4*sin(frameCount/29.7) + 0.3*noise(frameCount/42.34) + frameCount/77.8);
         let d = l*0.25 + sin(frameCount/33)*50 + noise(frameCount/12)*15;
         let x = 200 * sin(frameCount/55) + noise(frameCount/22)*150;
         let y = 200 * sin(frameCount/43) + noise(frameCount/32)*150;
         rect(x, y, d, d);
         pop();
      }
   }

}

function set_uniform(in_shader) {
  new Array(Nl)
  .fill()
  .map(function(_, ii){
      let rnd = [random(1.0/5.0),random(1.0/64.0) ,random(-1.0,1.0) ,random(-1.0,1.0)];
      in_shader.setUniform(`u_rnd${ii}`, rnd);
  });

   new Array(4)
  .fill()
  .map(function(_, ii){
     let u_c = color_set(rand_color_A());
      in_shader.setUniform(`u_color${ii}`, u_c);
  });

   new Array(2)
  .fill()
  .map(function(_, ii){
     var u_c = color_set(rand_color_B());
      in_shader.setUniform(`u_color${(ii+4)}`, u_c);
  });
}

function color_set(in_color) {
   let vec_color = [red(in_color)/255.0, green(in_color)/255.0, blue(in_color)/255.0];
   return vec_color;
}

function rand_color_A() {
   return color(random(360), random(50, 100), random(70, 100));
}

function rand_color_B() {
   return color(random(360), random(20, 90), random(70, 100));
}

//save jpg
function mousePressed() {
   save("img_" + month() + day() + hour() + minute() + second() + ".jpg");
}

